## Plan

### 1. `src/dolt/mod.rs` — Rewrite `DoltClient::connect` (lines 214-270)

Replace the `has_known_server` / `connect_timeout` block with:

```rust
pub async fn connect(config: &DoltConfig) -> Result<Self> {
    // 3s is plenty for localhost. Prevents N×10s hangs when scan_repos
    // calls connect sequentially across N repos with dead Dolt servers.
    let connect_timeout = std::time::Duration::from_secs(3);

    if config.port > 0 {
        if let Ok(Ok(pool)) = tokio::time::timeout(
            connect_timeout,
            pool_options().connect(&config.url()),
        )
        .await
        {
            let client = DoltClient { pool };
            client.enable_auto_dolt_commit().await;
            return Ok(client);
        }

        // Connect failed. Check whether the server process is still alive.
        // Alive but unresponsive → bail (don't displace a live server).
        // Dead (or no PID file) → clean up stale files, fall through to auto-start.
        let pid_file = config.beads_dir.join("dolt-server.pid");
        let pid_alive = std::fs::read_to_string(&pid_file)
            .ok()
            .and_then(|s| s.trim().parse::<u32>().ok())
            .map(crate::session::is_pid_alive)
            .unwrap_or(false);

        if pid_alive {
            anyhow::bail!(
                "Dolt server on port {} not responding ({}s timeout). \
                 Kill stale servers with: pkill -f 'dolt sql-server'",
                config.port,
                connect_timeout.as_secs()
            );
        }

        // Dead server — clean up stale files and fall through to auto-start.
        eprintln!(
            "[dolt] dead server on port {}, cleaning up and restarting...",
            config.port
        );
        let _ = std::fs::remove_file(&pid_file);
        let _ = std::fs::remove_file(config.beads_dir.join("dolt-server.port"));
        let _ = std::fs::remove_file(config.beads_dir.join("dolt-server.lock"));
    }

    // No responding server — auto-start from the dolt data directory.
    let dolt_dir = config.dolt_dir();
    if !dolt_dir.exists() {
        anyhow::bail!(
            "Dolt database not initialized for this repo.\n\
             Expected database at: {}\n\
             \n\
             To initialize, run:\n  rsry enable <repo-path>",
            dolt_dir.display()
        );
    }

    eprintln!("[dolt] auto-starting server for {}...", config.database);

    // Always allocate a fresh ephemeral port to avoid conflicts when restarting.
    let listener =
        std::net::TcpListener::bind("127.0.0.1:0").context("allocating ephemeral port")?;
    let port = listener.local_addr()?.port();
    drop(listener);
    // ... rest of spawn logic unchanged (lines 271-323)
```

Key diffs from current:
- Remove `has_known_server` variable
- `connect_timeout`: `if has_known_server { 10 } else { 3 }` → `Duration::from_secs(3)` (flat 3s)
- `if has_known_server { bail! }` → PID check: if alive bail, if dead clean+fallthrough
- Port allocation: remove `if config.port == 0 { ephemeral } else { config.port }` → always ephemeral

### 2. `src/scanner.rs` — Parallel `scan_repos`

Replace sequential for-loop (lines 9-19) with JoinSet:

```rust
use tokio::task::JoinSet;

pub async fn scan_repos(repos: &[RepoConfig]) -> Result<Vec<Bead>> {
    let mut all_beads = Vec::new();
    let mut set: JoinSet<(String, Result<Vec<Bead>>)> = JoinSet::new();

    for repo in repos {
        let path = expand_path(&repo.path);
        let beads_dir = path.join(".beads");
        if !beads_dir.exists() {
            continue;
        }
        let repo_name = repo.name.clone();
        set.spawn(async move {
            let result = read_beads(&beads_dir, &repo_name).await;
            (repo_name, result)
        });
    }

    while let Some(res) = set.join_next().await {
        match res {
            Ok((_, Ok(beads))) => all_beads.extend(beads),
            Ok((name, Err(e))) => eprintln!("warning: failed to read beads from {}: {e}", name),
            Err(e) => eprintln!("warning: scan task panicked: {e}"),
        }
    }

    // Sort: ready items first, then by priority (lower = higher priority)
    all_beads.sort_by(|a, b| {
        b.is_ready()
            .cmp(&a.is_ready())
            .then(a.priority.cmp(&b.priority))
    });

    Ok(all_beads)
}
```

Add `use tokio::task::JoinSet;` to imports.

