### Change 3: `src/pool.rs` — parallel pool connect

```rust
pub async fn from_config(config_path: &str) -> Result<Self> {
    use tokio::task::JoinSet;
    let cfg = config::load_merged(config_path)?;
    let mut set: JoinSet<(String, PathBuf, Option<Box<dyn BeadStore>>)> = JoinSet::new();

    for repo in &cfg.repo {
        let path = crate::scanner::expand_path(&repo.path);
        let beads_dir = path.join(".beads");
        if !beads_dir.exists() {
            continue;
        }
        let name = repo.name.clone();
        let path_clone = path.clone();
        set.spawn(async move {
            match crate::bead_sqlite::connect_bead_store(&beads_dir).await {
                Ok(store) => {
                    eprintln!("[pool] connected: {}", name);
                    (name, path_clone, Some(store))
                }
                Err(e) => {
                    eprintln!("[pool] skipping {} (connect failed: {e})", name);
                    (name, path_clone, None)
                }
            }
        });
    }

    let mut clients: HashMap<String, Box<dyn BeadStore>> = HashMap::new();
    let mut paths = HashMap::new();
    while let Some(res) = set.join_next().await {
        if let Ok((name, path, maybe_store)) = res {
            paths.insert(name.clone(), path);
            if let Some(store) = maybe_store {
                clients.insert(name, store);
            }
        }
    }

    Ok(RepoPool { clients, paths })
}
```

