/// Kill a running Dolt server and clean up its state files.
///
/// Used when the server is unresponsive. Dolt stores all data on-disk in
/// git format — no in-memory state is lost by killing the process.
fn kill_dolt_server(beads_dir: &std::path::Path) {
    let pid_file = beads_dir.join("dolt-server.pid");
    if let Ok(pid_str) = std::fs::read_to_string(&pid_file) {
        if let Ok(pid) = pid_str.trim().parse::<u32>() {
            unsafe {
                libc::kill(pid as i32, libc::SIGTERM);
            }
        }
    }
    let _ = std::fs::remove_file(&pid_file);
    let _ = std::fs::remove_file(beads_dir.join("dolt-server.port"));
    let _ = std::fs::remove_file(beads_dir.join("dolt-server.lock"));
}

/// Client for querying beads from a Dolt server.
pub struct DoltClient {
    pool: MySqlPool,
}

impl DoltClient {
    /// Connect to a Dolt server, auto-starting if not running.
    ///
    /// 1. Try connecting (3s timeout — enough for localhost)
    /// 2. If a known server didn't respond: kill it, clean up state files
    /// 3. Start `dolt sql-server` from the db directory
    /// 4. Wait for it to accept connections
    /// 5. Retry the MySQL connection
    pub async fn connect(config: &DoltConfig) -> Result<Self> {
        // 3s is enough for a local Dolt server. The old 10s timeout caused
        // N×10s hangs when scanning N repos with hung/stale servers.
        if config.port > 0 {
            if let Ok(Ok(pool)) = tokio::time::timeout(
                std::time::Duration::from_secs(3),
                pool_options().connect(&config.url()),
            )
            .await
            {
                let client = DoltClient { pool };
                client.enable_auto_dolt_commit().await;
                return Ok(client);
            }

            // Known server didn't respond — kill it and restart from the same
            // dolt_dir. Dolt data is on-disk (git format), so this is safe.
            eprintln!(
                "[dolt] server on port {} not responding — killing and restarting",
                config.port
            );
            kill_dolt_server(&config.beads_dir);
            tokio::time::sleep(std::time::Duration::from_millis(200)).await;
            // Fall through to auto-start below
        }

        // Auto-start from the dolt data directory
        let dolt_dir = config.dolt_dir();
        if !dolt_dir.exists() {
            anyhow::bail!(
                "Dolt database not initialized for this repo.\n\
                 Expected database at: {}\n\
                 \n\
                 To initialize, run:\n  rsry enable <repo-path>",
                dolt_dir.display()
            );
        }

        eprintln!("[dolt] auto-starting server for {}...", config.database);

        // Always allocate a fresh ephemeral port — avoids TIME_WAIT if we
        // just killed the previous server on the old port.
        let port = {
            let listener =
                std::net::TcpListener::bind("127.0.0.1:0").context("allocating ephemeral port")?;
            let port = listener.local_addr()?.port();
            drop(listener);
            port
