            Ok(beads) => all_beads.extend(beads),
            Err(e) => eprintln!("warning: scan task panicked: {e}"),
        }
    }

    all_beads.sort_by(|a, b| b.is_ready().cmp(&a.is_ready()).then(a.priority.cmp(&b.priority)));
    Ok(all_beads)
