    /// Connect to a Dolt server, auto-starting if not running.
    ///
    /// 1. Try connecting (3s timeout — fast-fail for dead servers)
    /// 2. If port was known but connect failed, re-check PID:
    ///    - PID alive → bail (server is hung, don't auto-restart)
    ///    - PID dead → clean stale files, fall through to auto-start
    /// 3. Start `dolt sql-server` on an ephemeral port
    /// 4. Wait for connections, then connect via MySQL
    pub async fn connect(config: &DoltConfig) -> Result<Self> {
        // 3s is sufficient for a healthy localhost connection.
        // (Was 10s: N dead repos × 10s = N×10s total hang time.)
        let has_known_server = config.port > 0;

        if let Ok(Ok(pool)) = tokio::time::timeout(
            std::time::Duration::from_secs(3),
            pool_options().connect(&config.url()),
        )
        .await
        {
            let client = DoltClient { pool };
            client.enable_auto_dolt_commit().await;
            return Ok(client);
        }

        // Connection failed. If we had a known port, check whether the server
        // process is still alive — handles the race between from_beads_dir's
        // PID check and this connect call.
        if has_known_server {
            let pid_file = config.beads_dir.join("dolt-server.pid");
            let server_alive = if pid_file.exists() {
                std::fs::read_to_string(&pid_file)
                    .ok()
                    .and_then(|s| s.trim().parse::<u32>().ok())
                    .map(crate::session::is_pid_alive)
                    .unwrap_or(false)
            } else {
                false
            };

            if server_alive {
                anyhow::bail!(
                    "Dolt server on port {} is running but not responding (3s timeout). \
                     Kill stale servers with: pkill -f 'dolt sql-server'",
                    config.port,
                );
            }

            // PID is dead — race between from_beads_dir PID check and this
            // connect.  Clean stale files and fall through to auto-restart.
            eprintln!(
                "[dolt] server on port {} died (stale pid), cleaning and restarting",
                config.port
            );
            let _ = std::fs::remove_file(&pid_file);
            let _ = std::fs::remove_file(config.beads_dir.join("dolt-server.port"));
            let _ = std::fs::remove_file(config.beads_dir.join("dolt-server.lock"));
        }

        // Auto-start path: no server running or stale files just cleaned above.
        let dolt_dir = config.dolt_dir();
        if !dolt_dir.exists() {
            anyhow::bail!(
                "Dolt database not initialized for this repo.\n\
                 Expected database at: {}\n\
                 \n\
                 To initialize, run:\n  rsry enable <repo-path>",
                dolt_dir.display()
            );
        }

        // Always allocate a fresh ephemeral port (old port, if any, is now stale).
        let port = {
            let listener =
                std::net::TcpListener::bind("127.0.0.1:0").context("allocating ephemeral port")?;
            let p = listener.local_addr()?.port();
            drop(listener);
            p
        };

        eprintln!(
            "[dolt] auto-starting server for {} on port {port}...",
            config.database
        );
