pub async fn scan_repos(repos: &[RepoConfig]) -> Result<Vec<Bead>> {
    let mut set = tokio::task::JoinSet::new();

    for repo in repos {
        let path = expand_path(&repo.path);
        let beads_dir = path.join(".beads");
        if !beads_dir.exists() {
            continue;
        }
        let name = repo.name.clone();
        set.spawn(async move {
            let result = read_beads(&beads_dir, &name).await;
            (name, result)
        });
    }

    let mut all_beads = Vec::new();
    while let Some(res) = set.join_next().await {
        match res {
            Ok((_, Ok(beads))) => all_beads.extend(beads),
            Ok((name, Err(e))) => eprintln!("warning: failed to read beads from {name}: {e}"),
            Err(e) => eprintln!("warning: scan task panicked: {e}"),
        }
    }

    // Sort: ready items first, then by priority (lower = higher priority)
    all_beads.sort_by(|a, b| {
        b.is_ready()
            .cmp(&a.is_ready())
            .then(a.priority.cmp(&b.priority))
    });

    Ok(all_beads)
}
```

**Why safe**: `BeadStore: Send + Sync` (defined in store.rs:190), so `Box<dyn BeadStore>` is Send. JoinSet::spawn requires Send + 'static — both satisfied. This makes N repos scan in O(max_single_timeout) instead of O(N * timeout).

