use std::collections::HashMap;
use std::path::{Path, PathBuf};
use std::sync::{Mutex, OnceLock};
use std::time::{Duration, Instant};

const CIRCUIT_BREAK_SECS: u64 = 30;

static FAILED_SERVERS: OnceLock<Mutex<HashMap<PathBuf, Instant>>> = OnceLock::new();

fn failed_servers() -> &'static Mutex<HashMap<PathBuf, Instant>> {
    FAILED_SERVERS.get_or_init(|| Mutex::new(HashMap::new()))
}

fn is_circuit_open(beads_dir: &Path) -> bool {
    let Ok(guard) = failed_servers().lock() else { return false; };
    guard.get(beads_dir).is_some_and(|t| t.elapsed() < Duration::from_secs(CIRCUIT_BREAK_SECS))
}

fn mark_circuit_open(beads_dir: &Path) {
    if let Ok(mut guard) = failed_servers().lock() {
        guard.insert(beads_dir.to_path_buf(), Instant::now());
    }
}

fn reset_circuit(beads_dir: &Path) {
    if let Ok(mut guard) = failed_servers().lock() { guard.remove(beads_dir); }
}
