    /// Backend name for logging
    pub backend: String,
}

pub struct ExecResult {
    pub exit_code: i32,
    pub stdout: String,
    pub stderr: String,
}

#[async_trait]
pub trait ExecutionBackend: Send + Sync {
    async fn provision(&self, opts: &ProvisionOpts) -> Result<ExecHandle>;
